def name_query(names):
    if not names:
        return ("SELECT id FROM users WHERE 0", ())
    return ("SELECT id FROM users WHERE name IN (" + ",".join("?" for _ in names) + ")", tuple(names))

def redact_headers(headers):
    sensitive = {"authorization", "cookie", "set-cookie", "x-api-key"}
    return [(name, "[REDACTED]" if name.lower() in sensitive else value) for name, value in headers]

def may_read(actor, resource):
    if actor.get("authenticated") is not True:
        return False
    if actor.get("role") == "admin":
        return True
    uid, owner = actor.get("id"), resource.get("owner_id")
    return isinstance(uid, str) and isinstance(owner, str) and bool(uid) and uid == owner

def grep_command(pattern, path):
    if not isinstance(pattern, str) or not isinstance(path, str) or "\x00" in pattern or "\x00" in path:
        raise ValueError("bad argument")
    return ["/usr/bin/grep", "-F", "--", pattern, path]

def suspicious_users(events, window, threshold):
    groups = {}
    for event in events:
        if event["outcome"] == "fail":
            groups.setdefault(event["user"], []).append(event["timestamp"])
    flagged = []
    for user, times in groups.items():
        times.sort()
        left = 0
        for right, time in enumerate(times):
            while time - times[left] > window:
                left += 1
            if right - left + 1 >= threshold:
                flagged.append(user)
                break
    return sorted(flagged)

